1	package netproxy
2	
3	import (
4		"bufio"
5		"bytes"
6		"context"
7		"crypto/tls"
8		"encoding/base64"
9		"errors"
10		"fmt"
11		"io"
12		"net"
13		"net/http"
14		"net/url"
15		"time"
16	)
17	
18	// maxConnectAnswer caps what is read while waiting for the answer to CONNECT: a
19	// proxy that never ends its header cannot make the check buffer without bound.
20	const maxConnectAnswer = 64 << 10
21	
22	// Dialer opens TLS connections along the path an https request would take. The
23	// zero value follows the proxy environment variables.
24	type Dialer struct {
25		// Proxy picks the proxy; nil means FromEnvironment.
26		Proxy Selector
27		// DialContext opens the TCP connection (to the proxy, or to the target when
28		// direct); nil means (&net.Dialer{}).DialContext.
29		DialContext func(ctx context.Context, network, addr string) (net.Conn, error)
30		// ProxyTLSConfig configures TLS to an https:// proxy; nil means system roots.
31		ProxyTLSConfig *tls.Config
32	}
33	
34	// DialTLS connects to hostport (the port is required) the way an https request
35	// to it would travel, then completes the handshake with cfg (ServerName
36	// defaults to the host). ctx bounds the whole: proxy dial, CONNECT, handshake.
37	//
38	// A failure of the proxy step is a *Error; a failure of the target itself (its
39	// handshake, its certificate) is returned as it would be without a proxy. The
40	// returned connection owns the tunnel: closing it closes the socket.
41	func (d Dialer) DialTLS(ctx context.Context, hostport string, cfg *tls.Config) (*tls.Conn, error) {
42		host, _, err := net.SplitHostPort(hostport)
43		if err != nil {
44			return nil, err
45		}
46		sel := d.Proxy
47		if sel == nil {
48			sel = FromEnvironment
49		}
50		proxy, err := sel(&url.URL{Scheme: "https", Host: hostport})
51		if err != nil {
52			return nil, &Error{Step: StepSelect, Err: err}
53		}
54		if proxy != nil && proxy.Scheme != "http" && proxy.Scheme != "https" {
55			return nil, &Error{Proxy: proxy.Host, Step: StepScheme, Err: errors.New(proxy.Scheme)}
56		}
57	
58		conn, err := d.tunnel(ctx, proxy, hostport)
59		if err != nil {
60			return nil, err
61		}
62	
63		tc := tls.Client(conn, targetConfig(cfg, host))
64		if err := tc.HandshakeContext(ctx); err != nil {
65			_ = conn.Close()
66			return nil, err
67		}
68		_ = conn.SetDeadline(time.Time{})
69		return tc, nil
70	}
71	
72	// tunnel returns a connection to hostport: direct when proxy is nil, otherwise
73	// through proxy by CONNECT. One deadline, ctx's, covers every step; on failure
74	// the connection is closed. The deadline is left set so the caller's handshake
75	// stays under it.
76	func (d Dialer) tunnel(ctx context.Context, proxy *url.URL, hostport string) (net.Conn, error) {
77		dial := d.DialContext
78		if dial == nil {
79			dial = (&net.Dialer{}).DialContext
80		}
81		if proxy == nil {
82			conn, err := dial(ctx, "tcp", hostport)
83			if err != nil {
84				return nil, err
85			}
86			if dl, ok := ctx.Deadline(); ok {
87				_ = conn.SetDeadline(dl)
88			}
89			return conn, nil
90		}
91	
92		addr := proxyAddr(proxy)
93		raw, err := dial(ctx, "tcp", addr)
94		if err != nil {
95			return nil, &Error{Proxy: addr, Step: StepDial, Err: err}
96		}
97		if dl, ok := ctx.Deadline(); ok {
98			_ = raw.SetDeadline(dl)
99		}
100		// A cancellation unblocks the reads and writes below by closing the socket.
101		stop := context.AfterFunc(ctx, func() { _ = raw.Close() })
102		conn, perr := d.connect(ctx, raw, proxy, addr, hostport)
103		if perr != nil {
104			stop()
105			return nil, perr
106		}
107		if !stop() {
108			// The cancellation fired after the CONNECT succeeded: the socket is closed.
109			_ = conn.Close()
110			return nil, &Error{Proxy: addr, Step: StepConnect, Err: ctx.Err()}
111		}
112		return conn, nil
113	}
114	
115	// connect runs TLS to the proxy when it is https://, then the CONNECT exchange,
116	// on conn. It closes conn on failure.
117	func (d Dialer) connect(ctx context.Context, conn net.Conn, proxy *url.URL, addr, hostport string) (net.Conn, *Error) {
118		fail := func(step Step, status int, err error) (net.Conn, *Error) {
119			_ = conn.Close()
120			if errors.Is(err, net.ErrClosed) && ctx.Err() != nil {
121				err = ctx.Err() // our own AfterFunc closed it: the cause is the context's
122			}
123			return nil, &Error{Proxy: addr, Step: step, StatusCode: status, Err: err}
124		}
125	
126		if proxy.Scheme == "https" {
127			cfg := &tls.Config{}
128			if d.ProxyTLSConfig != nil {
129				cfg = d.ProxyTLSConfig.Clone()
130			}
131			if cfg.ServerName == "" {
132				cfg.ServerName = proxy.Hostname()
133			}
134			tc := tls.Client(conn, cfg)
135			if err := tc.HandshakeContext(ctx); err != nil {
136				return fail(StepProxyTLS, 0, err)
137			}
138			conn = tc
139		}
140	
141		if _, err := io.WriteString(conn, connectRequest(proxy.User, hostport)); err != nil {
142			return fail(StepConnect, 0, err)
143		}
144		br := bufio.NewReader(io.LimitReader(conn, maxConnectAnswer))
145		resp, err := http.ReadResponse(br, &http.Request{Method: http.MethodConnect})
146		if err != nil {
147			return fail(StepConnect, 0, err)
148		}
149		// The body of a CONNECT answer is the tunnel; it is not read or closed here.
150		if resp.StatusCode != http.StatusOK {
151			return fail(StepConnect, resp.StatusCode, nil)
152		}
153		if n := br.Buffered(); n > 0 {
154			// Bytes read past the header belong to the tunnel; give them back first.
155			peeked, _ := br.Peek(n)
156			return &bufferedConn{Conn: conn, r: io.MultiReader(bytes.NewReader(bytes.Clone(peeked)), conn)}, nil
157		}
158		return conn, nil
159	}
160	
161	// bufferedConn is a net.Conn whose reads start with bytes already taken off it.
162	type bufferedConn struct {
163		net.Conn
164		r io.Reader
165	}
166	
167	func (c *bufferedConn) Read(p []byte) (int, error) { return c.r.Read(p) }
168	
169	// connectRequest is the CONNECT request for hostport, with Basic credentials
170	// from user when the proxy URL carries any.
171	func connectRequest(user *url.Userinfo, hostport string) string {
172		req := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n", hostport, hostport)
173		if user != nil {
174			password, _ := user.Password()
175			cred := base64.StdEncoding.EncodeToString([]byte(user.Username() + ":" + password))
176			req += "Proxy-Authorization: Basic " + cred + "\r\n"
177		}
178		return req + "\r\n"
179	}
180	
181	// proxyAddr is the proxy's host:port, without userinfo, with the scheme's
182	// default port when the URL has none.
183	func proxyAddr(proxy *url.URL) string {
184		if proxy.Port() != "" {
185			return proxy.Host
186		}
187		port := "80"
188		if proxy.Scheme == "https" {
189			port = "443"
190		}
191		return net.JoinHostPort(proxy.Hostname(), port)
192	}
193	
194	// targetConfig is a copy of cfg (or a fresh config) that verifies host unless
195	// cfg names another server.
196	func targetConfig(cfg *tls.Config, host string) *tls.Config {
197		c := &tls.Config{}
198		if cfg != nil {
199			c = cfg.Clone()
200		}
201		if c.ServerName == "" {
202			c.ServerName = host
203		}
204		return c
205	}
206

