1	package netproxy
2	
3	import (
4		"bufio"
5		"context"
6		"crypto/tls"
7		"crypto/x509"
8		"encoding/base64"
9		"errors"
10		"fmt"
11		"net"
12		"net/http"
13		"net/http/httptest"
14		"net/url"
15		"reflect"
16		"strconv"
17		"strings"
18		"sync"
19		"sync/atomic"
20		"testing"
21		"time"
22	
23		"github.com/anthnel/devdesk/internal/testutil/connectproxy"
24		"github.com/anthnel/devdesk/internal/testutil/loopback"
25	)
26	
27	// trackedConn remembers whether it was closed.
28	type trackedConn struct {
29		net.Conn
30		closed atomic.Bool
31	}
32	
33	func (c *trackedConn) Close() error {
34		c.closed.Store(true)
35		return c.Conn.Close()
36	}
37	
38	// tracker is a Dialer.DialContext that records every address asked for and
39	// every connection it opened.
40	type tracker struct {
41		mu    sync.Mutex
42		addrs []string
43		conns []*trackedConn
44	}
45	
46	func (tr *tracker) DialContext(ctx context.Context, network, addr string) (net.Conn, error) {
47		tr.mu.Lock()
48		tr.addrs = append(tr.addrs, addr)
49		tr.mu.Unlock()
50		c, err := (&net.Dialer{}).DialContext(ctx, network, addr)
51		if err != nil {
52			return nil, err
53		}
54		tc := &trackedConn{Conn: c}
55		tr.mu.Lock()
56		tr.conns = append(tr.conns, tc)
57		tr.mu.Unlock()
58		return tc, nil
59	}
