114	// rawProxy is a proxy that reads one request per connection and lets answer
115	// write whatever bytes it wants, for answers connectproxy refuses to produce.
116	func rawProxy(t *testing.T, answer func(conn net.Conn)) *url.URL {
117		t.Helper()
118		ln, err := net.Listen("tcp", "127.0.0.1:0")
119		if err != nil {
120			t.Fatal(err)
121		}
122		var (
123			mu    sync.Mutex
124			conns []net.Conn
125			wg    sync.WaitGroup
126			done  = make(chan struct{})
127		)
128		go func() {
129			defer close(done)
130			for {
131				c, err := ln.Accept()
132				if err != nil {
133					return
134				}
135				mu.Lock()
136				conns = append(conns, c)
137				mu.Unlock()
138				wg.Add(1)
139				go func() {
140					defer wg.Done()
141					defer func() { _ = c.Close() }()
142					if _, err := http.ReadRequest(bufio.NewReader(c)); err != nil {
143						return
144					}
145					answer(c)
146				}()
147			}
148		}()
149		t.Cleanup(func() {
150			_ = ln.Close()
151			<-done
152			mu.Lock()
153			for _, c := range conns {
154				_ = c.Close()
155			}
156			mu.Unlock()
157			wg.Wait()
158		})
159		return mustURL(t, "http://"+ln.Addr().String())
160	}
