162	// peerChain is the raw certificate chain the peer presented.
163	func peerChain(certs []*x509.Certificate) [][]byte {
164		var chain [][]byte
165		for _, c := range certs {
166			chain = append(chain, c.Raw)
167		}
168		return chain
169	}
