422	// TestDialTLSOneDeadlineCoversTheHandshake: the CONNECT succeeds, then the
423	// target never answers the handshake; the same deadline must end the wait, and
424	// the failure is the target's, not the proxy's.
425	func TestDialTLSOneDeadlineCoversTheHandshake(t *testing.T) {
426		held, err := net.Listen("tcp", "127.0.0.1:0")
427		if err != nil {
428			t.Fatal(err)
429		}
430		t.Cleanup(func() { _ = held.Close() })
