436		elapsed := time.Since(start)
437		if err == nil {
438			t.Fatal("DialTLS succeeded against a target that never answers")
439		}
440		var pe *Error
441		if errors.As(err, &pe) {
442			t.Fatalf("a stalled target handshake is reported as a proxy failure: %v", err)
443		}
444		var ne net.Error
445		isTimeout := errors.Is(err, context.DeadlineExceeded) || (errors.As(err, &ne) && ne.Timeout())
446		if !isTimeout {
447			t.Fatalf("error = %v, want a timeout", err)
448		}
449		if elapsed > time.Second {
450			t.Fatalf("returned after %v, want under 1s for a 200ms deadline", elapsed)
451		}
452	}
